window.AUTH=window.AUTH||{};window.AUTH["23-929"]={"d":"23-929","id":"2024/23-929","n":"Monsalvo Velazquez v. Garland","briefs":[{"k":"petitioner","label":"Brief of petitioner Hugo Abisai Monsalvo Velazquez","date":"2024-08-22","url":"https://www.supremecourt.gov/DocketPDF/23/23-929/323195/20240822163344698_Monsalvo%20Velazquez%20--%20Merits%20--%20Brief%20for%20Petitioner.pdf","side":"pet","n":67},{"k":"respondent","label":"Brief of respondent Merrick B.Garland, Attorney General","date":"2024-09-27","url":"https://www.supremecourt.gov/DocketPDF/23/23-929/327072/20240927164556380_23-929bsUnitedStates.pdf","side":"res","n":97},{"k":"reply","label":"Reply of petitioner Hugo Abisai Monsalvo Velazquez","date":"2024-10-28","url":"https://www.supremecourt.gov/DocketPDF/23/23-929/330370/20241028092547738_Monsalvo%20Velazquez%20--%20Merits%20--%20Reply%20Brief.pdf","side":"pet","n":23}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us2r27_e2pg.pdf","tr":true,"items":[{"t":"case","label":"Armstrong v. Tisch","cite":"835 F.2d 1139","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/835/1139/","by":{"0":"28, 32"}},{"t":"case","label":"Avery v. Stewart","cite":"2 Conn. 69","y":1816,"url":"https://www.courtlistener.com/c/Conn./2/69/","by":{"0":"23","1":"33, 34"}},{"t":"case","label":"Bacon v. State","cite":"22 Fla. 46","y":1886,"url":"https://www.courtlistener.com/c/Fla./22/46/","by":{"0":"22","1":"29"}},{"t":"case","label":"Bank of America Corp. v. City of Miami","cite":"581 U.S. 189","y":2017,"id":"2016/15-1111","sc":1,"sum":"The Court determined that the “aggrieved persons” language of the Fair Housing Act (FHA) does not impose a more narrow standing standard than Article III does and allows a city to sue, but the proximate cause standard requires the plaintiffs to show more than the possibility that a defendant could have foreseen the harm.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Barnes v. Eddy","cite":"12 R.I. 25","y":1878,"url":"https://www.courtlistener.com/c/R.I./12/25/","by":{"0":"22, 23","1":"30","2":"16"}},{"t":"case","label":"Barroso v. Gonzales","cite":"429 F.3d 1195","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/429/1195/","by":{"0":"13"}},{"t":"case","label":"Bullock v. Lincoln","cite":"2 Strange 914","y":1731,"court":"K.B.","url":"https://www.courtlistener.com/c/Strange/2/914/","by":{"0":"21"}},{"t":"case","label":"Carothers v. Wheeler","cite":"1 Or. 194","y":1855,"url":"https://www.courtlistener.com/c/Or./1/194/","by":{"0":"22","1":"30","2":"16"}},{"t":"case","label":"Cock v. Bunn","cite":"6 Johns. 326","y":1810,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Johns./6/326/","by":{"0":"22","1":"28-30"}},{"t":"case","label":"Commissioner v. Keystone Consol. Indus., Inc.","cite":"508 U.S. 152","y":1993,"id":"1992/91-1677","sc":1,"sum":"When applied to an employer's funding obligation, the contribution of unencumbered property to a defined benefit plan is a prohibited \"sale or exchange\" under §4975(c)(1)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Corner Post, Inc. v. Board of Governors","cite":"144 S. Ct. 2440","y":2024,"id":"2023/22-1008","sc":1,"sum":"An Administrative Procedures Act claim does not accrue for purposes of 28 U. S. C. §2401(a)—the default 6-year statute of limitations applicable to suits against the United States—until the plaintiff is injured by final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 29"}},{"t":"case","label":"Dada v. Mukasey","cite":"554 U.S. 1","y":2008,"id":"2007/06-1181","sc":1,"op":8,"ar":1,"sum":"Justice Anthony Kennedy, joined by four other Justices, stated that an alien has two options in such a case: he may abide by the terms of the voluntary departure and leave the country on time, maintaining the re-entry perks, or withdraw the voluntary departure request and remain in the country to pursue the motion to reopen. If the alien chooses the second option, he may become subject to deportation proceedings.","sumSrc":"Oyez","by":{"0":"6-9, 34","1":"2-6, 22, 43, 44"}},{"t":"case","label":"Davy v. Salter","cite":"6 Mod. 251","y":1704,"court":"K.B.","url":"https://www.courtlistener.com/c/Mod./6/251/","by":{"0":"2, 20, 21"}},{"t":"case","label":"George v. McDonough","cite":"596 U.S. 740","y":2022,"id":"2021/21-234","sc":1,"sum":"The invalidation of a Department of Veterans Affairs regulation after a veteran’s benefits decision becomes final cannot support a claim for collateral relief permitting revision of that decision based on “clear and unmistakable error” under 38 U. S. C. §§5109A and 7111.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Haig v. Agee","cite":"453 U.S. 280","y":1981,"id":"1980/80-83","sc":1,"op":1,"sum":"In a 7-to-2 decision, the Court held that Passport Act of 1926 and other congressional statutes implicitly granted the Secretary of State the power to revoke passports.","sumSrc":"Oyez","by":{"0":"2, 15, 35, 36, 43","2":"9"}},{"t":"case","label":"Hammond v. Am. Mut. Life Ins. Co.","cite":"10 Gray 306","y":1858,"court":"Mass.","url":"https://www.courtlistener.com/c/Gray/10/306/","by":{"0":"23"}},{"t":"case","label":"Harrow v. Department of Defense","cite":"601 U.S. 480","y":2024,"id":"2023/23-21","sc":1,"sum":"Title 5 U. S. C. §7703(b)(1)’s 60-day filing deadline for a federal employee to petition the Federal Circuit to review a final decision of the Merit Systems Protection Board is not jurisdictional.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36","2":"7"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Jorgji v. Mukasey","cite":"514 F.3d 53","y":2008,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/514/53/","by":{"0":"41"}},{"t":"case","label":"Lamson v. Andrews","cite":"40 App. D.C. 39","y":1913,"url":"https://www.courtlistener.com/c/App.%20D.C./40/39/","sum":"Holding that “the appellant was not obliged to perform the act . . . on that day, which happened to be Sunday, or the next succeeding day, which happened to be a legal holiday, each being dies non”.","sumSrc":"brief:0","by":{"0":"26","1":"40, 41"}},{"t":"case","label":"Lee v. Carlton","cite":"3 Term Rep. 642","y":1790,"court":"K.B.","url":"https://www.courtlistener.com/c/Term%20Rep./3/642/","sum":"Holding that “if the last of the four days [to plead] happen[ed] on a Sunday,” the defendant could plead “the next day,” because “otherwise” he would effectively “be limited to three days”.","sumSrc":"brief:0","by":{"0":"21"}},{"t":"case","label":"LeGras v. AETNA Life Ins. Co.","cite":"786 F.3d 1233","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/1233/","by":{"0":"28"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"2, 14, 16, 17, 29, 31","2":"21, 22"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"op":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35, 43"}},{"t":"case","label":"Malley v. Briggs","cite":"475 U.S. 335","y":1986,"id":"1985/84-1586","sc":1,"sum":"The Court held that a police officer was not entitled to immunity when he caused an unlawful arrest by presenting a judge with an application for a warrant that did not present a probable cause.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Meyer v. Holley","cite":"537 U.S. 280","y":2003,"id":"2002/01-1120","sc":1,"sum":"The Court held that the FHA imposes liability without fault upon the employer in accordance with traditional agency principles. In other words, the FHA normally imposes vicarious liability upon the corporation, but not upon its officers or owners.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Meza-Vallejos v. Holder","cite":"669 F.3d 920","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/669/920/","op":1,"ar":1,"by":{"0":"13"}},{"t":"case","label":"Monroe Cattle Co. v. Becker","cite":"147 U.S. 47","y":1893,"id":"scdb/1892-060","sc":1,"sum":"During the ninety days allowed by the statutes of Texas concerning the purchase of school lands to a purchaser to make his first payment, (Laws, of 1879, special session, p. 23, Laws of 1881, p, 119,) it is not competent for the surveyor to permit a person who had filed an application for a designated tract to treat the application as withdrawn and abandoned, and to make another application for the same tract in the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26","1":"40, 41","2":"20"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Nat’l Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"op":6,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"10, 12","1":"8","2":"2, 14"}},{"t":"case","label":"Norfolk Redev. & Hous. Auth. v. Chesapeake & Potomac Tel. Co.","cite":"464 U.S. 30","y":1983,"id":"1983/81-2332","sc":1,"sum":"C&P is not a \"displaced person\" within the meaning of the Act. The Act did not change the long-established common-law principle that a utility forced to relocate from a public right-of-way must do so at its own expense. An analysis of the Act-the purposes of which were to ensure that persons displaced by federal and federally funded programs would receive uniform treatment and would not suffer disproportionate …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 18, 31"}},{"t":"case","label":"Norfolk S. Ry. Co. v. Sorrell","cite":"549 U.S. 158","y":2007,"id":"2006/05-746","sc":1,"sum":"The Court ruled unanimously that the causation standard for employee negligence is the same as the standard for railroad negligence.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"People v. Caldbeck","cite":"466 P.3d 1174","y":2020,"court":"Colo. O.P.D.J.","url":"https://www.courtlistener.com/c/P.3d/466/1174/","by":{"0":"11"}},{"t":"case","label":"Pereira v. Sessions","cite":"585 U.S. 198","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"0":"10, 12"}},{"t":"case","label":"Post v. Garrow","cite":"26 N.W. 580","y":1886,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W./26/580/","by":{"0":"23, 32","1":"34"}},{"t":"case","label":"R. v. Ginever","cite":"6 Term Rep. 594","y":1796,"court":"K.B.","url":"https://www.courtlistener.com/c/Term%20Rep./6/594/","sum":"Explaining that a four-day period starting on Friday, January 29, “did not expire until Wednesday the 3d of February (Tuesday being a dies non)”.","sumSrc":"brief:0","by":{"0":"22"}},{"t":"case","label":"Salter v. Burt","cite":"20 Wend. 205","y":1838,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Wend./20/205/","sum":"Noting Nebraska statute prohibiting labor on Sundays.","sumSrc":"brief:1","by":{"0":"23","1":"34, 41"}},{"t":"case","label":"Salvador-Calleros v. Ashcroft","cite":"389 F.3d 959","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/389/959/","by":{"0":"13"}},{"t":"case","label":"Sherwood Bros. v. District of Columbia","cite":"113 F.2d 162","y":1940,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/113/162/","ar":1,"by":{"0":"25, 28, 32, 46","1":"40, 41","2":"16, 20, 21"}},{"t":"case","label":"Street v. United States","cite":"133 U.S. 299","y":1890,"id":"scdb/1889-113","sc":1,"ar":2,"sum":"It was the purpose of Congress by the 12th and 13th sections' of the army-appropriation act of July 15, 1870,16 Stat. 318, 319, to reduce the number of officers in the army, and to that end § 11 authorized the President to eliminate from it officers who were unfit for the discharge of their duties by reason of a cause which had no meritorious.claim upon the consideration of' the government, while § 12 made a general …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19, 24, 28, 31, 32","1":"37-40","2":"16, 18-20"}},{"t":"case","label":"Swann v. Broome","cite":"1 Black. W. 526","y":1764,"court":"K.B.","url":"https://www.courtlistener.com/c/Black.%20W./1/526/","by":{"0":"21"}},{"t":"case","label":"Union Nat’l Bank v. Lamb","cite":"337 U.S. 38","y":1949,"id":"scdb/1948-075","sc":1,"sum":"1. A judgment of the highest court of a State determining a claim of right under the Full Faith and Credit Clause of the Federal Constitution is reviewable here not by appeal but by certiorari; and the papers whereon an appeal has been improvidently taken in such a case may be treated as a petition for a writ of certiorari. 28 U. S. C. §§ 1257 (3), 2103. Pp. 39-40..2. Where the last day of the period within which a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25-28, 31","1":"39, 40","2":"16, 17, 19, 20-22"}},{"t":"case","label":"United Mine Workers of America v. Dole","cite":"870 F.2d 662","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/870/662/","by":{"0":"28"}},{"t":"case","label":"United States v. Bestfoods","cite":"524 U.S. 51","y":1998,"id":"1997/97-454","sc":1,"sum":"But a corporate parent that actively participated in, and exercised control over, the operations of the facility itself may be held directly liable in its own right as an operator of the facility.","sumSrc":"Oyez","by":{"0":"18","2":"14"}},{"t":"case","label":"United States v. Hill","cite":"506 U.S. 546","y":1993,"id":"1992/91-1421","sc":1,"op":2,"sum":"The term \"adjusted basis,\" as used in §57(a)(8), does not include the depreciable drilling and development costs identified in Treas. Reg. § 1.612-4(c)(1).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 42"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 18"}},{"t":"case","label":"Wathen v. Beaumont","cite":"11 East 271","y":1809,"court":"K.B.","url":"https://www.courtlistener.com/c/East/11/271/","sum":"Stating that the rule for pleading deadlines “in actions in general” was that “a Sunday or a holiday reckons as a day, except it be the last” (emphasis added).","sumSrc":"brief:0","by":{"0":"22"}},{"t":"const","label":"Article I, Section 7, Clause 2","clauses":[["presentment","Presentment Clause and the Veto"]],"text":"Every Bill which shall have passed the House of Representatives and the Senate, shall, before it become a Law, be presented to the President of the United States; If he approve he shall sign it, but if not he shall return it, with his Objections to that House in which it shall have originated, who shall enter the Objections at large on their Journal, and proceed to reconsider it. If after such Reconsideration two thirds of that House shall agree to pass the Bill, it shall be sent, together with the Objections, to the other House, by which it shall likewise be reconsidered, and if approved by two thirds of that House, it shall become a Law. But in all such Cases the Votes of both Houses shall be determined by yeas and Nays, and the Names of the Persons voting for and against the Bill shall be entered on the Journal of each House respectively. If any Bill shall not be returned by the President within ten Days (Sundays excepted) after it shall have been presented to him, the Same shall be a Law, in like Manner as if he had signed it, unless the Congress by their Adjournment prevent its Return, in which Case it shall not be a Law.","by":{"0":"23"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"7, 27, 37, 42","1":"4","2":"1, 8-11, 13, 15, 17, 22"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(a)"],"by":{"0":"17"}},{"t":"usc","label":"22 U.S.C. § 211a","url":"https://www.law.cornell.edu/uscode/text/22/211a","by":{"0":"36"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"18"}},{"t":"reg","label":"14 C.F.R. § 302.8","url":"https://www.ecfr.gov/current/title-14/section-302.8","by":{"0":"42"}},{"t":"reg","label":"16 C.F.R. § 4.3","url":"https://www.ecfr.gov/current/title-16/section-4.3","subs":["(a)"],"by":{"0":"42"}},{"t":"reg","label":"20 C.F.R. § 725.311","url":"https://www.ecfr.gov/current/title-20/section-725.311","by":{"0":"42"}},{"t":"reg","label":"32 C.F.R. § 150.7","url":"https://www.ecfr.gov/current/title-32/section-150.7","by":{"0":"42"}},{"t":"reg","label":"45 C.F.R. § 501.7","url":"https://www.ecfr.gov/current/title-45/section-501.7","subs":["(a)"],"by":{"0":"42"}},{"t":"reg","label":"49 C.F.R. § 821.10","url":"https://www.ecfr.gov/current/title-49/section-821.10","by":{"0":"42"}},{"t":"reg","label":"52 Fed. Reg. 2931","url":"https://www.govinfo.gov/link/fr/52/2931","by":{"0":"37, 38"}},{"t":"reg","label":"62 Fed. Reg. 10,312","url":"https://www.govinfo.gov/link/fr/62/10312","by":{"0":"7"}},{"t":"reg","label":"65 Fed. Reg. 76,121","url":"https://www.govinfo.gov/link/fr/65/76121","by":{"0":"40","2":"11"}},{"t":"reg","label":"68 Fed. Reg. 9824","url":"https://www.govinfo.gov/link/fr/68/9824","by":{"0":"38"}},{"t":"reg","label":"86 Fed. Reg. 70,708","url":"https://www.govinfo.gov/link/fr/86/70708","by":{"0":"46"}},{"t":"rule","label":"Fed. R. App. P. 26","url":"https://www.law.cornell.edu/rules/frap/rule_26","subs":["(a)"],"by":{"0":"28"}},{"t":"case","label":"Brief Amicus Curiae of the General Conference of Seventh-day Adventists, Groff v. DeJoy","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45"}},{"t":"case","label":"Brief Amicus Curiae of the Union of Orthodox Jewish Congregations of America, Groff v. DeJoy","cite":"600 U.S. 447","y":2023,"id":"2022/22-174","sc":1,"sum":"Title VII requires an employer that denies a religious accommodation to show that the burden of granting an accommodation would result in substantial increased costs in relation to the conduct of its particular business.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45"}},{"t":"case","label":"Alderman v. Phelps","cite":"15 Mass. 225","y":1818,"url":"https://www.courtlistener.com/c/Mass./15/225/","sum":"Finding “[no] reason why the last day of the [30-day period for a postjudgment lien set by statute] should be excluded because it happens to be Sunday”.","sumSrc":"brief:1","by":{"1":"28"}},{"t":"case","label":"American Tobacco Co. v. Strickling","cite":"41 A. 1083","y":1898,"court":"Md.","url":"https://www.courtlistener.com/c/A./41/1083/","sum":"Finding “no valid reason for excluding the last Sunday” when a statutory bill-of-exception filing period “expire[s] on Sunday”.","sumSrc":"brief:1","by":{"1":"28"}},{"t":"case","label":"Barton v. Barr","cite":"590 U.S. 222","y":2020,"id":"2019/18-725","sc":1,"op":10,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"Bissell v. Bissell","cite":"11 Barb. 96","y":1851,"court":"N.Y. Gen. Term","url":"https://www.courtlistener.com/c/Barb./11/96/","by":{"1":"29"}},{"t":"case","label":"Braddeley v. Adams","cite":"101 Eng. Rep. 97","y":1793,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./101/97/","sum":"Explaining that litigants on such “a dies non juridicus” could conduct “such business as is transacted at the Judges’ chambers”.","sumSrc":"brief:1","by":{"1":"25"}},{"t":"case","label":"California Pub. Employees’ Retirement Sys. v. ANZ Sec., Inc.","cite":"582 U.S. 497","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"sum":"A case which the Court vacated in part and remanded in favor of the defendant without addressing the Fourth Amendment question at issue.","sumSrc":"Oyez","by":{"1":"20, 21"}},{"t":"case","label":"Carey v. Reilly","cite":"46 N.Y.S. 449","y":1897,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/N.Y.S./46/449/","sum":"Concluding that Saturday “is not dies non juridicus, and does not prevent courts from continuing their sessions, and performing any judicial business which may come before them”.","sumSrc":"brief:1","by":{"1":"37"}},{"t":"case","label":"Catholic Legal Immigration Network, Inc. v. Executive Office for Immigration Review","cite":"2021 WL 3609986","y":2021,"court":"D.D.C. Apr. 4","by":{"1":"3"}},{"t":"case","label":"Centro Legal de la Raza v. Executive Office for Immigration Review","cite":"524 F. Supp. 3d 919","y":2021,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/524/919/","by":{"1":"3"}},{"t":"case","label":"Cousins v. Commonwealth","cite":"187 Va. 506","y":1948,"url":"https://www.courtlistener.com/c/Va./187/506/","sum":"Explaining that “[l]egal holidays have generally not been placed on the same basis in the transaction of business as Sunday” and that the state legislature had not vested Saturday with special legal significance.","sumSrc":"brief:1","by":{"1":"36"}},{"t":"case","label":"Dade County Planning Dep’t v. Ransing","cite":"158 So. 2d 528","y":1963,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/158/528/","by":{"1":"30"}},{"t":"case","label":"Danville v. Brown","cite":"128 U.S. 503","y":1888,"id":"scdb/1888-057","sc":1,"sum":"In computing the “ sixty days after the rendition of judgment,” allowed by Sev. Stat. § 1007 to a party appealing from a judgment of a Circuit Court to give the security required by law, Sundays are excluded.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24, 25"}},{"t":"case","label":"Drake v. Andrews","cite":"2 Mich. 203","y":1851,"url":"https://www.courtlistener.com/c/Mich./2/203/","sum":"Concluding that Alderman’s approach “seems applicable to every statute” specifying one-week-or-longer periods to act.","sumSrc":"brief:1","by":{"1":"28"}},{"t":"case","label":"Drury v. Defontaine","cite":"127 Eng. Rep. 781","y":1808,"court":"C.P.","url":"https://www.courtlistener.com/c/Eng.%20Rep./127/781/","by":{"1":"31, 32"}},{"t":"case","label":"Erie R.R. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Hammond v. American Mut. Life Ins. Co.","cite":"76 Mass. 306","y":1858,"url":"https://www.courtlistener.com/c/Mass./76/306/","sum":"Explaining that “[t]he statute law forbids” the “performance of contracts and doing secular business” on Sunday.","sumSrc":"brief:1","by":{"1":"34, 41"}},{"t":"case","label":"Harker v. Addis","cite":"4 Pa. 515","y":1846,"url":"https://www.courtlistener.com/c/Pa./4/515/","sum":"Explaining that Goswiler reflects that “the law does not allow the act to be done” on Sunday.","sumSrc":"brief:1","by":{"1":"28"}},{"t":"case","label":"Horacek v. Keebler","cite":"5 Neb. 355","y":1877,"url":"https://www.courtlistener.com/c/Neb./5/355/","sum":"Noting Nebraska statute prohibiting labor on Sundays.","sumSrc":"brief:1","by":{"1":"33, 34"}},{"t":"case","label":"Houston, E. & W. Tex. Ry. v. Harding","cite":"63 Tex. 162","y":1885,"url":"https://www.courtlistener.com/c/Tex./63/162/","sum":"Concluding that a statutory holiday is not “a dies non juridicus” unless the legislature designates it as such.","sumSrc":"brief:1","by":{"1":"25"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"op":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Mata v. Lynch","cite":"576 U.S. 143","y":2015,"id":"2014/14-185","sc":1,"op":3,"ar":12,"sum":"The Court held that circuit courts of appeals have jurisdiction over Board of Immigration Appeals decisions to deny motions to reopen immigration proceedings.","sumSrc":"Oyez","by":{"1":"16","2":"4"}},{"t":"case","label":"Mesure v. Britten","cite":"126 Eng. Rep. 736","y":1796,"court":"C.P.","url":"https://www.courtlistener.com/c/Eng.%20Rep./126/736/","by":{"1":"25"}},{"t":"case","label":"Mumford v. Buel","cite":"1 Root 145","y":1789,"court":"Conn. Super. Ct.","url":"https://www.courtlistener.com/c/Root/1/145/","by":{"1":"33"}},{"t":"case","label":"Nasrallah v. Barr","cite":"590 U.S. 573","y":2020,"id":"2019/18-1432","sc":1,"op":32,"ar":16,"sum":"The Court held that the federal courts have jurisdiction to review an administrative agency’s factual findings underlying denials of withholding (and deferral) of removal relief, notwithstanding 8 U.S.C. § 1252(a)(2)(C), which seems to divest courts of jurisdiction in such cases.","sumSrc":"Oyez","by":{"1":"11, 12, 16-20","2":"4, 5"}},{"t":"case","label":"Neal v. Crew","cite":"12 Ga. 93","y":1852,"url":"https://www.courtlistener.com/c/Ga./12/93/","by":{"1":"28"}},{"t":"case","label":"Peacock v. The Queen","cite":"140 Eng. Rep. 1085","y":1858,"court":"C.P.","url":"https://www.courtlistener.com/c/Eng.%20Rep./140/1085/","by":{"1":"27"}},{"t":"case","label":"Pressed Steel Car Co. v. Eastern Ry.","cite":"121 F. 609","y":1903,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./121/609/","by":{"1":"40"}},{"t":"case","label":"Rodriguez v. FDIC","cite":"589 U.S. 132","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/132/","sc":1,"op":1,"by":{"1":"42","2":"14"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Simmons v. Hanne","cite":"39 So. 77","y":1905,"court":"Fla.","url":"https://www.courtlistener.com/c/So./39/77/","by":{"1":"29, 30"}},{"t":"case","label":"Smith v. Sparrow","cite":"130 Eng. Rep. 700","y":1827,"court":"C.P.","url":"https://www.courtlistener.com/c/Eng.%20Rep./130/700/","by":{"1":"32"}},{"t":"case","label":"State v. Lewis","cite":"31 Wash. 515","y":1903,"url":"https://www.courtlistener.com/c/Wash./31/515/","by":{"1":"25"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Stone v. United States","cite":"167 U.S. 178","y":1897,"id":"scdb/1896-194","sc":1,"sum":"The United States court in the District of Washington has jurisdiction of an action brought by the United States against a defendant, found there, to recover for timber unlawfully cut from lands of the United States in Idaho.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"25, 26"}},{"t":"case","label":"Story v. Elliot","cite":"8 Cow. 27","y":1827,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Cow./8/27/","sum":"Noting similar New York statute.","sumSrc":"brief:1","by":{"1":"31, 34"}},{"t":"case","label":"Swann v. Broome","cite":"97 Eng. Rep. 999","y":1764,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./97/999/","by":{"1":"24-26, 31"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"sum":"The Court ruled that Congress did not intend the \"equitable tolling\" doctrine to apply to the Internal Revenue Code of 1986's time limitations for filing tax refund claims.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Vailes v. Brown","cite":"27 P. 945","y":1891,"court":"Colo.","url":"https://www.courtlistener.com/c/P./27/945/","by":{"1":"28"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. NRDC","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Walker v. Hazen","cite":"90 F.2d 502","y":1937,"url":"https://www.courtlistener.com/c/F.2d/90/502/","by":{"1":"41"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"20"}},{"t":"usc","label":"28 U.S.C. § 2341","url":"https://www.law.cornell.edu/uscode/text/28/2341","by":{"1":"16"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","stext":{"head":"§2342. Jurisdiction of court of appeals","paras":[[0,"The court of appeals (other than the United States Court of Appeals for the Federal Circuit) has exclusive jurisdiction to enjoin, set aside, suspend (in whole or in part), or to determine the validity of—"],[1,"(1) all final orders of the Federal Communication Commission made reviewable by section 402(a) of title 47;"],[1,"(2) all final orders of the Secretary of Agriculture made under chapters 9 and 20A of title 7, except orders issued under sections 210(e), 217a, and 499g(a) of title 7;"],[1,"(3) all rules, regulations, or final orders of—"],[2,"(A) the Secretary of Transportation issued pursuant to section 50501, 50502, 56101–56104, or 57109 of title 46 or pursuant to part B or C of subtitle IV, subchapter III of chapter 311, chapter 313, or chapter 315 of title 49; and"],[2,"(B) the Federal Maritime Commission issued pursuant to section 305,1 41304, 41308, or 41309 or chapter 421 or 441 of title 46;"],[1,"(4) all final orders of the Atomic Energy Commission made reviewable by section 2239 of title 42;"],[1,"(5) all rules, regulations, or final orders of the Surface Transportation Board made reviewable by section 2321 of this title;"],[1,"(6) all final orders under section 812 of the Fair Housing Act; and"],[1,"(7) all final agency actions described in section 20114(c) of title 49."],[0,"Jurisdiction is invoked by filing a petition as provided by section 2344 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2342?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2342. Jurisdiction of court of appeals","tname":"Judiciary and Judicial Procedure","by":{"1":"16"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)","(a)(47)(A)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"1":"2, 2, 17"}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)(3)","(g)(1)"],"stext":{"head":"§1103. Powers and duties of the Secretary, the Under Secretary, and the Attorney General","paras":[[0,"(a) Secretary of Homeland Security"],[0,"(1) The Secretary of Homeland Security shall be charged with the administration and enforcement of this chapter and all other laws relating to the immigration and naturalization of aliens, except insofar as this chapter or such laws relate to the powers, functions, and duties conferred upon the President, Attorney General, the Secretary of State, the officers of the Department of State, or diplomatic or consular officers: Provided, however, That determination and ruling by the Attorney General with respect to all questions of law shall be controlling."],[0,"(2) He shall have control, direction, and supervision of all employees and of all the files and records of the Service."],[0,"(3) He shall establish such regulations; prescribe such forms of bond, reports, entries, and other papers; issue such instructions; and perform such other acts as he deems necessary for carrying out his authority under the provisions of this chapter."],[0,"(4) He may require or authorize any employee of the Service or the Department of Justice to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon any other employee of the Service."],[0,"(5) He shall have the power and duty to control and guard the boundaries and borders of the United States against the illegal entry of aliens and shall, in his discretion, appoint for that purpose such number of employees of the Service as to him shall appear necessary and proper."],[0,"(6) He is authorized to confer or impose upon any employee of the United States, with the consent of the head of the Department or other independent establishment under whose jurisdiction the employee is serving, any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(7) He may, with the concurrence of the Secretary of State, establish offices of the Service in foreign countries; and, after consultation with the Secretary of State, he may, whenever in his judgment such action may be necessary to accomplish the purposes of this chapter, detail employees of the Service for duty in foreign countries."],[0,"(8) After consultation with the Secretary of State, the Attorney General may authorize officers of a foreign country to be stationed at preclearance facilities in the United States for the purpose of ensuring that persons traveling from or through the United States to that foreign country comply with that country's immigration and related laws."],[0,"(9) Those officers may exercise such authority and perform such duties as United States immigration officers are authorized to exercise and perform in that foreign country under reciprocal agreement, and they shall enjoy such reasonable privileges and immunities necessary for the performance of their duties as the government of their country extends to United States immigration officers."],[0,"(10) In the event the Attorney General determines that an actual or imminent mass influx of aliens arriving off the coast of the United States, or near a land border, presents urgent circumstances requiring an immediate Federal response, the Attorney General may authorize any State or local law enforcement officer, with the consent of the head of the department, agency, or establishment under whose jurisdiction the individual is serving, to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(11) The Attorney General, in support of persons in administrative detention in non-Federal institutions, is authorized—"],[1,"(A) to make payments from funds appropriated for the administration and enforcement of the laws relating to immigration, naturalization, and alien registration for necessary clothing, medical care, necessary guard hire, and the housing, care, and security of persons detained by the Service pursuant to Federal law under an agreement with a State or political subdivision of a State; and"],[1,"(B) to enter into a cooperative agreement with any State, territory, or political subdivision thereof, for the necessary construction, physical renovation, acquisition of equipment, supplies or materials required to establish acceptable conditions of confinement and detention services in any State or unit of local government which agrees to provide guaranteed bed space for persons detained by the Service."],[0,"(b) Land acquisition authority"],[0,"(1) The Attorney General may contract for or buy any interest in land, including temporary use rights, adjacent to or in the vicinity of an international land border when the Attorney General deems the land essential to control and guard the boundaries and borders of the United States against any violation of this chapter."],[0,"(2) The Attorney General may contract for or buy any interest in land identified pursuant to paragraph (1) as soon as the lawful owner of that interest fixes a price for it and the Attorney General considers that price to be reasonable."],[0,"(3) When the Attorney General and the lawful owner of an interest identified pursuant to paragraph (1) are unable to agree upon a reasonable price, the Attorney General may commence condemnation proceedings pursuant to section 3113 of title 40."],[0,"(4) The Attorney General may accept for the United States a gift of any interest in land identified pursuant to paragraph (1)."],[0,"(c) Commissioner; appointment"],[0,"The Commissioner shall be a citizen of the United States and shall be appointed by the President, by and with the advice and consent of the Senate. He shall be charged with any and all responsibilities and authority in the administration of the Service and of this chapter which are conferred upon the Attorney General as may be delegated to him by the Attorney General or which may be prescribed by the Attorney General. The Commissioner may enter into cooperative agreements with State and local law enforcement agencies for the purpose of assisting in the enforcement of the immigration laws."],[0,"(d) Statistical information system"],[0,"(1) The Commissioner, in consultation with interested academicians, government agencies, and other parties, shall provide for a system for collection and dissemination, to Congress and the public, of information (not in individually identifiable form) useful in evaluating the social, economic, environmental, and demographic impact of immigration laws."],[0,"(2) Such information shall include information on the alien population in the United States, on the rates of naturalization and emigration of resident aliens, on aliens who have been admitted, paroled, or granted asylum, on nonimmigrants in the United States (by occupation, basis for admission, and duration of stay), on aliens who have not been admitted or have been removed from the United States, on the number of applications filed and granted for cancellation of removal, and on the number of aliens estimated to be present unlawfully in the United States in each fiscal year."],[0,"(3) Such system shall provide for the collection and dissemination of such information not less often than annually."],[0,"(e) Annual report"],[0,"(1) The Commissioner shall submit to Congress annually a report which contains a summary of the information collected under subsection (d) and an analysis of trends in immigration and naturalization."],[0,"(2) Each annual report shall include information on the number, and rate of denial administratively, of applications for naturalization, for each district office of the Service and by national origin group."],[0,"(f) Minimum number of agents in States"],[0,"The Attorney General shall allocate to each State not fewer than 10 full-time active duty agents of the Immigration and Naturalization Service to carry out the functions of the Service, in order to ensure the effective enforcement of this chapter."],[0,"(g) Attorney General"],[0,"(1) In general"],[1,"The Attorney General shall have such authorities and functions under this chapter and all other laws relating to the immigration and naturalization of aliens as were exercised by the Executive Office for Immigration Review, or by the Attorney General with respect to the Executive Office for Immigration Review, on the day before the effective date of the Immigration Reform, Accountability and Security Enhancement Act of 2002."],[0,"(2) Powers"],[1,"The Attorney General shall establish such regulations, prescribe such forms of bond, reports, entries, and other papers, issue such instructions, review such administrative determinations in immigration proceedings, delegate such authority, and perform such other acts as the Attorney General determines to be necessary for carrying out this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1103?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1103. Powers and duties of the Secretary, the Under Secretary, and the Attorney General","tname":"Aliens and Nationality","by":{"1":"44, 44"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(9)(A)(i)","(a)(9)(A)(ii)"],"by":{"1":"4, 4"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(c)(1)(A)","(c)(6)(B)","(c)(7)","(c)(7)(B)","(c)(7)(C)(i)","(e)(2)"],"stext":{"head":"§1229a. Removal proceedings","paras":[[0,"(a) Proceeding"],[0,"(1) In general"],[1,"An immigration judge shall conduct proceedings for deciding the inadmissibility or deportability of an alien."],[0,"(2) Charges"],[1,"An alien placed in proceedings under this section may be charged with any applicable ground of inadmissibility under section 1182(a) of this title or any applicable ground of deportability under section 1227(a) of this title."],[0,"(3) Exclusive procedures"],[1,"Unless otherwise specified in this chapter, a proceeding under this section shall be the sole and exclusive procedure for determining whether an alien may be admitted to the United States or, if the alien has been so admitted, removed from the United States. Nothing in this section shall affect proceedings conducted pursuant to section 1228 of this title."],[0,"(b) Conduct of proceeding"],[0,"(1) Authority of immigration judge"],[1,"The immigration judge shall administer oaths, receive evidence, and interrogate, examine, and cross-examine the alien and any witnesses. The immigration judge may issue subpoenas for the attendance of witnesses and presentation of evidence. The immigration judge shall have authority (under regulations prescribed by the Attorney General) to sanction by civil money penalty any action (or inaction) in contempt of the judge's proper exercise of authority under this chapter."],[0,"(2) Form of proceeding"],[0,"(A) In general"],[2,"The proceeding may take place—"],[3,"(i) in person,"],[3,"(ii) where agreed to by the parties, in the absence of the alien,"],[3,"(iii) through video conference, or"],[3,"(iv) subject to subparagraph (B), through telephone conference."],[0,"(B) Consent required in certain cases"],[2,"An evidentiary hearing on the merits may only be conducted through a telephone conference with the consent of the alien involved after the alien has been advised of the right to proceed in person or through video conference."],[0,"(3) Presence of alien"],[1,"If it is impracticable by reason of an alien's mental incompetency for the alien to be present at the proceeding, the Attorney General shall prescribe safeguards to protect the rights and privileges of the alien."],[0,"(4) Alien's rights in proceeding"],[1,"In proceedings under this section, under regulations of the Attorney General—"],[2,"(A) the alien shall have the privilege of being represented, at no expense to the Government, by counsel of the alien's choosing who is authorized to practice in such proceedings,"],[2,"(B) the alien shall have a reasonable opportunity to examine the evidence against the alien, to present evidence on the alien's own behalf, and to cross-examine witnesses presented by the Government but these rights shall not entitle the alien to examine such national security information as the Government may proffer in opposition to the alien's admission to the United States or to an application by the alien for discretionary relief under this chapter, and"],[2,"(C) a complete record shall be kept of all testimony and evidence produced at the proceeding."],[0,"(5) Consequences of failure to appear"],[0,"(A) In general"],[2,"Any alien who, after written notice required under paragraph (1) or (2) of section 1229(a) of this title has been provided to the alien or the alien's counsel of record, does not attend a proceeding under this section, shall be ordered removed in absentia if the Service establishes by clear, unequivocal, and convincing evidence that the written notice was so provided and that the alien is removable (as defined in subsection (e)(2)). The written notice by the Attorney General shall be considered sufficient for purposes of this subparagraph if provided at the most recent address provided under section 1229(a)(1)(F) of this title."],[0,"(B) No notice if failure to provide address information"],[2,"No written notice shall be required under subparagraph (A) if the alien has failed to provide the address required under section 1229(a)(1)(F) of this title."],[0,"(C) Rescission of order"],[2,"Such an order may be rescinded only—"],[3,"(i) upon a motion to reopen filed within 180 days after the date of the order of removal if the alien demonstrates that the failure to appear was because of exceptional circumstances (as defined in subsection (e)(1)), or"],[3,"(ii) upon a motion to reopen filed at any time if the alien demonstrates that the alien did not receive notice in accordance with paragraph (1) or (2) of section 1229(a) of this title or the alien demonstrates that the alien was in Federal or State custody and the failure to appear was through no fault of the alien."],[2,"The filing of the motion to reopen described in clause (i) or (ii) shall stay the removal of the alien pending disposition of the motion by the immigration judge."],[0,"(D) Effect on judicial review"],[2,"Any petition for review under section 1252 of this title of an order entered in absentia under this paragraph shall (except in cases described in section 1252(b)(5) of this title) be confined to (i) the validity of the notice provided to the alien, (ii) the reasons for the alien's not attending the proceeding, and (iii) whether or not the alien is removable."],[0,"(E) Additional application to certain aliens in contiguous territory"],[2,"The preceding provisions of this paragraph shall apply to all aliens placed in proceedings under this section, including any alien who remains in a contiguous foreign territory pursuant to section 1225(b)(2)(C) of this title."],[0,"(6) Treatment of frivolous behavior"],[1,"The Attorney General shall, by regulation—"],[2,"(A) define in a proceeding before an immigration judge or before an appellate administrative body under this subchapter, frivolous behavior for which attorneys may be sanctioned,"],[2,"(B) specify the circumstances under which an administrative appeal of a decision or ruling will be considered frivolous and will be summarily dismissed, and"],[2,"(C) impose appropriate sanctions (which may include suspension and disbarment) in the case of frivolous behavior."],[1,"Nothing in this paragraph shall be construed as limiting the authority of the Attorney General to take actions with respect to inappropriate behavior."],[0,"(7) Limitation on discretionary relief for failure to appear"],[1,"Any alien against whom a final order of removal is entered in absentia under this subsection and who, at the time of the notice described in paragraph (1) or (2) of section 1229(a) of this title, was provided oral notice, either in the alien's native language or in another language the alien understands, of the time and place of the proceedings and of the consequences under this paragraph of failing, other than because of exceptional circumstances (as defined in subsection (e)(1)) to attend a proceeding under this section, shall not be eligible for relief under section 1229b, 1229c, 1255, 1258, or 1259 of this title for a period of 10 years after the date of the entry of the final order of removal."],[0,"(c) Decision and burden of proof"],[0,"(1) Decision"],[0,"(A) In general"],[2,"At the conclusion of the proceeding the immigration judge shall decide whether an alien is removable from the United States. The determination of the immigration judge shall be based only on the evidence produced at the hearing."],[0,"(B) Certain medical decisions"],[2,"If a medical officer or civil surgeon or board of medical officers has certified under section 1222(b) of this title that an alien has a disease, illness, or addiction which would make the alien inadmissible under paragraph (1) of section 1182(a) of this title, the decision of the immigration judge shall be based solely upon such certification."],[0,"(2) Burden on alien"],[1,"In the proceeding the alien has the burden of establishing—"],[2,"(A) if the alien is an applicant for admission, that the alien is clearly and beyond doubt entitled to be admitted and is not inadmissible under section 1182 of this title; or"],[2,"(B) by clear and convincing evidence, that the alien is lawfully present in the United States pursuant to a prior admission."],[1,"In meeting the burden of proof under subparagraph (B), the alien shall have access to the alien's visa or other entry document, if any, and any other records and documents, not considered by the Attorney General to be confidential, pertaining to the alien's admission or presence in the United States."],[0,"(3) Burden on service in cases of deportable aliens"],[0,"(A) In general"],[2,"In the proceeding the Service has the burden of establishing by clear and convincing evidence that, in the case of an alien who has been admitted to the United States, the alien is deportable. No decision on deportability shall be valid unless it is based upon reasonable, substantial, and probative evidence."],[0,"(B) Proof of convictions"],[2,"In any proceeding under this chapter, any of the following documents or records (or a certified copy of such an official document or record) shall constitute proof of a criminal conviction:"],[3,"(i) An official record of judgment and conviction."],[3,"(ii) An official record of plea, verdict, and sentence."],[3,"(iii) A docket entry from court records that indicates the existence of the conviction."],[3,"(iv) Official minutes of a court proceeding or a transcript of a court hearing in which the court takes notice of the existence of the conviction."],[3,"(v) An abstract of a record of conviction prepared by the court in which the conviction was entered, or by a State official associated with the State's repository of criminal justice records, that indicates the charge or section of law violated, the disposition of the case, the existence and date of conviction, and the sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229a?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§1229a. Removal proceedings","tname":"Aliens and Nationality","by":{"1":"17, 43, 5, 8, 9, 5, 43, 17"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(b)"],"by":{"1":"8"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","subs":["(b)","(b)(1)","(b)(1)(A)","(b)(1)(D)","(b)(2)","(b)(3)","(d)(1)"],"stext":{"head":"§1229c. Voluntary departure","paras":[[0,"(a) Certain conditions"],[0,"(1) In general"],[1,"The Attorney General may permit an alien voluntarily to depart the United States at the alien's own expense under this subsection, in lieu of being subject to proceedings under section 1229a of this title or prior to the completion of such proceedings, if the alien is not deportable under section 1227(a)(2)(A)(iii) or section 1227(a)(4)(B) of this title."],[0,"(2) Period"],[0,"(A) In general"],[2,"Subject to subparagraph (B), permission to depart voluntarily under this subsection shall not be valid for a period exceeding 120 days."],[0,"(B) Three-year pilot program waiver"],[2,"During the period October 1, 2000, through September 30, 2003, and subject to subparagraphs (C) and (D)(ii), the Attorney General may, in the discretion of the Attorney General for humanitarian purposes, waive application of subparagraph (A) in the case of an alien—"],[3,"(i) who was admitted to the United States as a nonimmigrant visitor (described in section 1101(a)(15)(B) of this title) under the provisions of the visa waiver pilot program established pursuant to section 1187 of this title, seeks the waiver for the purpose of continuing to receive medical treatment in the United States from a physician associated with a health care facility, and submits to the Attorney General—"],[4,"(I) a detailed diagnosis statement from the physician, which includes the treatment being sought and the expected time period the alien will be required to remain in the United States;"],[4,"(II) a statement from the health care facility containing an assurance that the alien's treatment is not being paid through any Federal or State public health assistance, that the alien's account has no outstanding balance, and that such facility will notify the Service when the alien is released or treatment is terminated; and"],[4,"(III) evidence of financial ability to support the alien's day-to-day expenses while in the United States (including the expenses of any family member described in clause (ii)) and evidence that any such alien or family member is not receiving any form of public assistance; or"],[3,"(ii) who—"],[4,"(I) is a spouse, parent, brother, sister, son, daughter, or other family member of a principal alien described in clause (i); and"],[4,"(II) entered the United States accompanying, and with the same status as, such principal alien."],[0,"(C) Waiver limitations"],[2,"(i) Waivers under subparagraph (B) may be granted only upon a request submitted by a Service district office to Service headquarters."],[2,"(ii) Not more than 300 waivers may be granted for any fiscal year for a principal alien under subparagraph (B)(i)."],[2,"(iii)(I) Except as provided in subclause (II), in the case of each principal alien described in subparagraph (B)(i) not more than one adult may be granted a waiver under subparagraph (B)(ii)."],[2,"(II) Not more than two adults may be granted a waiver under subparagraph (B)(ii) in a case in which—"],[3,"(aa) the principal alien described in subparagraph (B)(i) is a dependent under the age of 18; or"],[3,"(bb) one such adult is age 55 or older or is physically handicapped."],[0,"(D) Report to Congress; suspension of waiver authority"],[2,"(i) Not later than March 30 of each year, the Commissioner shall submit to the Congress an annual report regarding all waivers granted under subparagraph (B) during the preceding fiscal year."],[2,"(ii) Notwithstanding any other provision of law, the authority of the Attorney General under subparagraph (B) shall be suspended during any period in which an annual report under clause (i) is past due and has not been submitted."],[0,"(3) Bond"],[1,"The Attorney General may require an alien permitted to depart voluntarily under this subsection to post a voluntary departure bond, to be surrendered upon proof that the alien has departed the United States within the time specified."],[0,"(4) Treatment of aliens arriving in the United States"],[1,"In the case of an alien who is arriving in the United States and with respect to whom proceedings under section 1229a of this title are (or would otherwise be) initiated at the time of such alien's arrival, paragraph (1) shall not apply. Nothing in this paragraph shall be construed as preventing such an alien from withdrawing the application for admission in accordance with section 1225(a)(4) of this title."],[0,"(b) At conclusion of proceedings"],[0,"(1) In general"],[1,"The Attorney General may permit an alien voluntarily to depart the United States at the alien's own expense if, at the conclusion of a proceeding under section 1229a of this title, the immigration judge enters an order granting voluntary departure in lieu of removal and finds that—"],[2,"(A) the alien has been physically present in the United States for a period of at least one year immediately preceding the date the notice to appear was served under section 1229(a) of this title;"],[2,"(B) the alien is, and has been, a person of good moral character for at least 5 years immediately preceding the alien's application for voluntary departure;"],[2,"(C) the alien is not deportable under section 1227(a)(2)(A)(iii) or section 1227(a)(4) of this title; and"],[2,"(D) the alien has established by clear and convincing evidence that the alien has the means to depart the United States and intends to do so."],[0,"(2) Period"],[1,"Permission to depart voluntarily under this subsection shall not be valid for a period exceeding 60 days."],[0,"(3) Bond"],[1,"An alien permitted to depart voluntarily under this subsection shall be required to post a voluntary departure bond, in an amount necessary to ensure that the alien will depart, to be surrendered upon proof that the alien has departed the United States within the time specified."],[0,"(c) Aliens not eligible"],[0,"The Attorney General shall not permit an alien to depart voluntarily under this section if the alien was previously permitted to so depart after having been found inadmissible under section 1182(a)(6)(A) of this title."],[0,"(d) Civil penalty for failure to depart"],[0,"(1) In general"],[1,"Subject to paragraph (2), if an alien is permitted to depart voluntarily under this section and voluntarily fails to depart the United States within the time period specified, the alien—"],[2,"(A) shall be subject to a civil penalty of not less than $1,000 and not more than $5,000; and"],[2,"(B) shall be ineligible, for a period of 10 years, to receive any further relief under this section and sections 1229b, 1255, 1258, and 1259 of this title."],[0,"(2) Application of VAWA protections"],[1,"The restrictions on relief under paragraph (1) shall not apply to relief under section 1229b or 1255 of this title on the basis of a petition filed by a VAWA self-petitioner, or a petition filed under section 1229b(b)(2) of this title, or under section 1254(a)(3) of this title (as in effect prior to March 31, 1997), if the extreme cruelty or battery was at least one central reason for the alien's overstaying the grant of voluntary departure."],[0,"(3) Notice of penalties"],[1,"The order permitting an alien to depart voluntarily shall inform the alien of the penalties under this subsection."],[0,"(e) Additional conditions"],[0,"The Attorney General may by regulation limit eligibility for voluntary departure under this section for any class or classes of aliens. No court may review any regulation issued under this subsection."],[0,"(f) Judicial review"],[0,"No court shall have jurisdiction over an appeal from denial of a request for an order of voluntary departure under subsection (b), nor shall any court order a stay of an alien's removal pending consideration of any claim with respect to voluntary departure."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229c?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":4,"head":"§1229c. Voluntary departure","tname":"Aliens and Nationality","by":{"1":"7, 7, 7, 7, 7, 7, 7, 7"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(b)(3)","(c)(3)(A)(ii)(III)"],"by":{"1":"7, 22"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)","(a)(4)","(a)(5)","(b)(6)","(b)(9)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":23,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"1":"22, 22, 22, 22, 22, 22"}},{"t":"usc","label":"8 U.S.C. § 1252b","url":"https://www.law.cornell.edu/uscode/text/8/1252b","subs":["(e)(2)(A)(1994)"],"by":{"1":"22"}},{"t":"usc","label":"28 U.S.C. § 350","url":"https://www.law.cornell.edu/uscode/text/28/350","subs":["(1946)"],"by":{"1":"39"}},{"t":"usc","label":"28 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/28/2101","subs":["(c)"],"by":{"1":"39, 40"}},{"t":"rule","label":"Fed. R. App. P. 45","url":"https://www.law.cornell.edu/rules/frap/rule_45","subs":["(a)(2)"],"by":{"1":"27"}},{"t":"rule","label":"Fed. R. Crim. P. 56","url":"https://www.law.cornell.edu/rules/frcrmp/rule_56","subs":["(a)"],"by":{"1":"27"}},{"t":"reg","label":"61 Fed. Reg. 18,900","url":"https://www.govinfo.gov/link/fr/61/18900","by":{"1":"44"}},{"t":"reg","label":"73 Fed. Reg. 76,927","url":"https://www.govinfo.gov/link/fr/73/76927","by":{"1":"6"}},{"t":"reg","label":"85 Fed. Reg. 81,588","url":"https://www.govinfo.gov/link/fr/85/81588","by":{"1":"3"}},{"t":"case","label":"Air Courier Conference v. Am. Postal Workers Union","cite":"498 U.S. 517","y":1991,"id":"1990/89-1416","sc":1,"sum":"The United States Postal Service's monopoly over the carriage of letters in and from the Nation is codified in a group of statutes known as the Private Express Statutes (PES). The monopoly was created by Congress as a revenue protection measure for the Postal Service vis-A-vis private competitors. Pursuant to a PES provision allowing it to suspend PES restrictions as to any mail route where the public interest so …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Bioconvergence LLC v. Attariwala","cite":"2019 WL 8139811","y":2019,"court":"S.D. Ind. Dec. 18","by":{"2":"18"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Mary Kay Inc. v. Wilson","cite":"2013 WL 12100773","y":2013,"court":"N.D. Tex. Apr. 1","by":{"2":"18"}},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"sum":"Title 8 U. S. C. §1252(d)(1)—which requires noncitizens to “exhaus[t] all administrative remedies . . . as of right” before challenging a Board of Immigration Appeals final order of removal in federal court—is not a jurisdictional provision and does not require noncitizens to request discretionary forms of review.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"7"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"2":"8"}},{"t":"rule","label":"Fed. R. Civ. P. 6","url":"https://www.law.cornell.edu/rules/frcp/rule_6","subs":["(a)"],"by":{"2":"16, 19, 20"}}]};